CREATE DATABASE IF NOT EXISTS gods_eye CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gods_eye;
DROP TABLE IF EXISTS audit_log,alerts,incidents,threats,response_teams,users;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','OPERATOR','VIEWER') NOT NULL DEFAULT 'VIEWER',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE incidents(id INT AUTO_INCREMENT PRIMARY KEY,incident_type VARCHAR(120) NOT NULL,description TEXT,location VARCHAR(180) NOT NULL,severity ENUM('Low','Medium','High','Critical') NOT NULL DEFAULT 'Low',status ENUM('Open','Investigating','Resolved') NOT NULL DEFAULT 'Open',reported_by INT NOT NULL,date_reported TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reported_by) REFERENCES users(id));
CREATE TABLE threats(id INT AUTO_INCREMENT PRIMARY KEY,threat_type VARCHAR(120) NOT NULL,description TEXT,severity ENUM('Low','Medium','High','Critical') NOT NULL DEFAULT 'Low',status ENUM('Monitoring','Active','Contained','Closed') NOT NULL DEFAULT 'Monitoring',detected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE response_teams(id INT AUTO_INCREMENT PRIMARY KEY,team_name VARCHAR(120) NOT NULL,department VARCHAR(120) NOT NULL,contact VARCHAR(80),status ENUM('Available','Busy','Offline') NOT NULL DEFAULT 'Available');
CREATE TABLE alerts(id INT AUTO_INCREMENT PRIMARY KEY,incident_id INT NULL,message VARCHAR(255) NOT NULL,level ENUM('Low','Medium','High','Critical') NOT NULL DEFAULT 'Medium',status ENUM('Open','Acknowledged','Closed') NOT NULL DEFAULT 'Open',alert_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(incident_id) REFERENCES incidents(id) ON DELETE SET NULL);
CREATE TABLE audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120) NOT NULL,details TEXT,action_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
